"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["75324"],{28665(e){e.exports=JSON.parse('{"id":"FIN-1382","slug":"contango","term":"Contango","also_known_as":[],"difficulty":"Advanced","definition":"Contango is a situation in a futures market where futures prices for later delivery dates are higher than the current spot price or prices for nearer delivery dates.","explanation":["Contango is common in markets for commodities that are costly to store, such as oil, natural gas and metals. Futures prices for later delivery tend to be higher because they reflect the costs of storing the commodity, insuring it and financing it until delivery.","For example, if crude oil trades at 70 per barrel in the spot market and a futures contract for delivery in six months trades at 73, the market is in contango.","Contango affects investors who hold commodity exposure through futures, such as many commodity exchange-traded funds. As contracts approach expiry, they must be sold and replaced with later contracts at higher prices. This roll process can create losses over time even if spot prices do not change, a cost known as negative roll yield.","Deep contango can signal oversupply, when there is more of a commodity available today than needed. In April 2020, with oil storage nearly full, extreme contango contributed to one US oil futures contract briefly trading below zero."],"note":"","total":1500,"prev":{"slug":"contactless-payment","term":"Contactless Payment"},"next":{"slug":"contingent-liability","term":"Contingent Liability"}}')}}]);